<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>UNIFCO Technician</title><style>:root{font-family:Inter,Arial,sans-serif;--navy:#1e315b;--dark:#132137;--red:#ce122d;--muted:#68758a}*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:var(--dark)}.top{position:sticky;top:0;z-index:10;background:#fff;border-bottom:1px solid #e4e9f0;padding:12px 16px;display:flex;align-items:center;gap:12px}.logo{width:52px;height:52px;object-fit:contain}.top strong{color:var(--navy)}.wrap{width:min(760px,94%);margin:16px auto 90px}.offline{display:none;padding:10px 12px;border-radius:10px;background:#fff6e5;color:#8a5a00;margin-bottom:12px}.offline.show{display:block}.card{background:#fff;border:1px solid #e3e8ef;border-radius:15px;padding:16px;margin-bottom:13px;box-shadow:0 3px 12px rgba(19,33,55,.05)}.row{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.wo{font-size:18px;font-weight:800;color:var(--navy)}.pill{padding:4px 8px;border-radius:999px;background:#eef3fa;font-size:12px}.actions{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:13px}.btn{border:0;border-radius:10px;padding:12px;background:var(--navy);color:#fff;font-weight:750}.btn.red{background:var(--red)}label{display:grid;gap:5px;font-size:13px;font-weight:700;margin-top:9px}input,select,textarea{padding:11px;border:1px solid #ccd5e2;border-radius:9px;font:inherit}textarea{min-height:90px}.bottom{position:fixed;left:0;right:0;bottom:0;background:#fff;border-top:1px solid #dde3ec;display:flex;justify-content:center;gap:8px;padding:10px}.bottom a{padding:10px 14px;border-radius:9px;color:var(--navy);text-decoration:none;font-weight:700}.statusmsg{padding:10px;border-radius:9px;background:#eaf8ef;color:#207a43;margin-bottom:12px}@media(min-width:720px){.actions{grid-template-columns:repeat(4,1fr)}}</style></head><body><header class="top"><img class="logo" src="{{ route('brand.logo') }}" alt="UNIFCO"><div><strong>Technician Mobile</strong><div style="font-size:12px;color:var(--muted)">Assigned work · offline-aware execution</div></div></header><main class="wrap">@if(session('status'))<div class="statusmsg">{{ session('status') }}</div>@endif<div id="offline" class="offline">Offline mode: status updates will be queued locally and retried when the connection returns.</div>
@forelse($assignments as $a) @php($w=$workOrders->get($a->work_order_id))<section class="card"><div class="row"><div><div class="wo">{{ $w?->work_order_no }}</div><div style="color:var(--muted);margin-top:4px">{{ $w?->maintenance_type }} · {{ $w?->priority }} · {{ $a->scheduled_start?->format('Y-m-d H:i') }}</div></div><span class="pill">{{ $a->dispatch_status }}</span></div><div class="actions">@foreach(['ACCEPTED'=>'Accept','ARRIVED'=>'Arrived','IN_PROGRESS'=>'Start','COMPLETED'=>'Complete'] as $value=>$label)<form class="status-form" method="POST" action="{{ route('field.technician.status',$a) }}">@csrf<input type="hidden" name="status" value="{{ $value }}"><button class="btn {{ $value==='COMPLETED'?'red':'' }}">{{ $label }}</button></form>@endforeach</div><form method="POST" action="{{ route('field.inspections.store') }}" style="margin-top:14px">@csrf<input type="hidden" name="work_order_id" value="{{ $a->work_order_id }}"><label>Inspection template<select name="inspection_template_id"><option value="">General inspection</option>@foreach(\App\Models\InspectionTemplate::where('status','ACTIVE')->orderBy('name')->get() as $t)<option value="{{ $t->id }}">{{ $t->template_no }} · {{ $t->name }}</option>@endforeach</select></label><label>Checklist / readings<textarea name="responses"></textarea></label><label>Findings<textarea name="findings"></textarea></label><label>Recommendations<textarea name="recommendations"></textarea></label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="complete" value="1"> Mark inspection complete</label><button class="btn" style="margin-top:10px;width:100%">Save inspection</button></form></section>@empty<div class="card">No work orders are assigned to this technician.</div>@endforelse</main><nav class="bottom"><a href="{{ route('field.technician') }}">Work</a><a href="{{ route('field.assistant') }}">AI Assistant</a><a href="{{ route('platform.notifications.index') }}">Alerts</a></nav><script>const banner=document.getElementById('offline');function onlineState(){banner.classList.toggle('show',!navigator.onLine);if(navigator.onLine)flushQueue()}window.addEventListener('online',onlineState);window.addEventListener('offline',onlineState);onlineState();document.querySelectorAll('.status-form').forEach(f=>f.addEventListener('submit',e=>{if(navigator.onLine)return;e.preventDefault();const q=JSON.parse(localStorage.getItem('unifco-status-queue')||'[]');q.push({url:f.action,status:f.querySelector('[name=status]').value,token:f.querySelector('[name=_token]').value});localStorage.setItem('unifco-status-queue',JSON.stringify(q));alert('Saved offline. It will sync automatically.')}));async function flushQueue(){let q=JSON.parse(localStorage.getItem('unifco-status-queue')||'[]'),remaining=[];for(const x of q){try{const r=await fetch(x.url,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-CSRF-TOKEN':x.token},body:'_token='+encodeURIComponent(x.token)+'&status='+encodeURIComponent(x.status)});if(!r.ok)remaining.push(x)}catch(e){remaining.push(x)}}localStorage.setItem('unifco-status-queue',JSON.stringify(remaining))}</script></body></html>